from taf.sbts.oam.coam.admin import admin

from taf.rfrl.procedures.resources.python.status_check.status_selector.StatusSelector import StatusSelector
from taf.rfrl.procedures.resources.python.status_check.exceptions import RmodIdForCellIdNotFound, InvalidCellVariant
from taf.rfrl.procedures.resources.python.logger.logger import log_input_and_output, log_env_state


class Cell(object):
    def __init__(self, variant, connection, cell_id=None):
        self._variant = variant
        self._status_selector = StatusSelector()
        self._api = admin()
        self._is_shared = None
        self._is_iot = None
        self._sharing_state = None
        self._cell_id = cell_id
        self._cell_type = None
        self._connection_alias = connection

    @property
    def is_shared(self):
        """
        Information whether cell is shared between more than one Radio Module or ASIR Module or between them
        :return: True or False depending on cell being shared between more than one RMOD/ASIRMOD or between them
        :rtype: bool
        """
        if self._is_shared is None and self._cell_id:
            self._is_shared = self._is_cell_shared()

        return self._is_shared

    @property
    def is_iot(self):
        """
        Information whether cell is from NB-IoT cell technology
        :return: True or False depending on cell being of NB-IoT cell technology
        :rtype: bool
        """
        if self._is_iot is None and self._cell_id:
            self._is_iot = self._is_iot_cell()
        return self._is_iot

    @property
    def sharing_rmods_state(self):
        """
        Information on the statuses of RMODs and ASIRMODs that share the cell.
        If cell is not shared, then it will return None.
        :return: None when cell is not shared between more than one RMOD or ASIRMOD or between them,
                 disabled when all the sharing RMODs/ASIRMODs are disabled
                 partially_disabled when at least one of the RMOD/ASIRMOD is disabled (but not all of them)
                 partially_locked when at least one of the RMOD/ASIRMOD is locked (but not all of them)
                 locked when all the sharing RMODs/ASIRMODs are locked
                 unlocked when none of the sharing RMODs/ASIRMODs are locked
        :rtype: Union(None, str)
        """
        if not self.is_shared:
            return None

        if self._sharing_state is None:
            sharing_rmod_ids = self._get_rmod_ids_for_cell_id()
            sharing_rmods_statuses = self._get_statuses_of_sharing_rmods(sharing_rmod_ids=sharing_rmod_ids)
            self._sharing_state = self._get_sharing_state(sharing_rmods_statuses=sharing_rmods_statuses)

        return self._sharing_state

    def get_expected_statuses(self):
        """
        Returns expected values of statuses.
        :return: dictionary with statuses names as keys and expected statuses values as values
        :rtype: dict(str, str)
        """
        if self._variant == 'active':
            return self._get_active_statuses()
        elif self._variant == 'online':
            return self._get_online_statuses()
        elif self._variant == 'offline':
            return self._get_offline_statuses()
        elif self._variant == 'failed':
            return self._get_failed_statuses()
        elif self._variant == 'dependency':
            return self._get_dependency_statuses()
        elif self._variant == 'blocked':
            return self._get_blocked_statuses()
        elif self._variant == 'locked':
            return self._get_locked_statuses()
        elif self._variant == 'degraded':
            return self._get_degraded_statuses()
        elif self._variant == 'dedicated_for_rat_reset':
            return self._get_dedicated_for_rat_reset_statuses()
        elif self._variant == 'energy_saving':
            return self._get_energy_saving_statuses()
        elif self._variant == 'reduced_energy_saving':
            return self._get_reduced_energy_saving_statuses()
        else:
            raise InvalidCellVariant("Provided cell variant does not exist: {}".format(self._variant))

    def _get_failed_statuses(self):
        pass

    def _get_dependency_statuses(self):
        pass

    def _get_blocked_statuses(self):
        pass

    def _get_locked_statuses(self):
        pass

    def _get_online_statuses(self):
        pass

    def _get_offline_statuses(self):
        pass

    def _get_active_statuses(self):
        pass

    def _get_degraded_statuses(self):
        pass

    def _get_dedicated_for_rat_reset_statuses(self):
        pass

    def _get_energy_saving_statuses(self):
        pass

    def _get_reduced_energy_saving_statuses(self):
        pass

    def _get_statuses_of_sharing_rmods(self, sharing_rmod_ids):
        """
        Gets statuses of specific RMOD
        :param sharing_rmod_ids: IDs of RMODs and ASIRMODs, e.g.:
            {'rmod': ["1", "2", "3"], 'asirmod': ["1", "3"]}
        :type sharing_rmod_ids: dict
        :return: dict of statuses sets for rmods and asirmods, e.g.:
            {
             "operationalState": {'enabled', 'disabled'},
             "administrativeState": {'locked', 'unlocked'}
            }

        :rtype: dict
        """
        rmods_statuses = self._get_statuses_of_all_rmods()
        sharing_rmods_statuses = {'operationalState': set(),
                                  'administrativeState': set()}

        for rmod_obj, rmod_ids in sharing_rmod_ids.items():
            for rmod_id in rmod_ids:
                rmod_status = rmods_statuses[rmod_obj][rmod_id]
                sharing_rmods_statuses['operationalState'].add(rmod_status['operationalState'].lower())
                sharing_rmods_statuses['administrativeState'].add(rmod_status['administrativeState'].lower())

        return sharing_rmods_statuses

    def _get_sharing_state(self, sharing_rmods_statuses):
        operational_state = sharing_rmods_statuses['operationalState']
        administrative_state = sharing_rmods_statuses['administrativeState']

        if "enabled" not in operational_state:
            return "disabled"
        elif {"disabled", "enabled"}.issubset(operational_state):
            return "partially_disabled"
        elif "unlocked" in administrative_state and "locked" not in administrative_state:
            return "unlocked"
        elif "locked" in administrative_state and "unlocked" not in administrative_state:
            return "locked"
        elif {"unlocked", "locked"}.issubset(administrative_state):
            return "partially_locked"

    def _is_cell_shared(self):
        """
        Determines whether cell of given cell_type and cell_id is shared between more than one RMOD.
        :return: info whether given cell is shared between more than one RMOD/ASIRMOD or between them
        :rtype: bool
        """
        rmods_list = []
        for rmod_obj, rmod_ids in self._get_rmod_ids_for_cell_id().items():
            rmods_list += rmod_ids

        return len(rmods_list) > 1

    def _get_rmod_ids_for_cell_id(self):
        """
        Gets RMOD/ASIRMOD ids for particular cell id (defined as cell_id in class initialization)
        :return: statuses for all rmods and asirmods e.g.:
            {'rmod': ["1", "2"], 'asirmod': ["1"]}
        :rtype: dict
        :raise RmodIdForCellIdNotFound when RMOD/ASIRMD ID for particular cell id was not found.
        """
        rmods_cell_ids = self._get_cell_ids_for_all_rus()

        rmods_dict = {}
        for rmod_obj in rmods_cell_ids:
            rmod_ids = []
            for rmod_id, cell_ids in rmods_cell_ids[rmod_obj].items():
                if str(self._cell_id) in cell_ids:
                    rmod_ids.append(rmod_id)
            rmods_dict[rmod_obj] = rmod_ids

        if not self._check_if_rmod_id_exists(rmods_dict):
            raise RmodIdForCellIdNotFound("Related rmod ID couldn't be found for {} "
                                          "cell ID: {}".format(self._cell_type, self._cell_id))

        return rmods_dict

    def _check_if_rmod_id_exists(self, rmods_dict):
        """
        Checks if any RMOD or ASIRMOD ID exists in provided rmod dictionary
        :param rmods_dict: IDs of RMODs and ASIRMODs, e.g.:
            {'rmod': ["1", "2", "3"], 'asirmod': ["1", "3"]}
        :type rmods_dict: dict
        :return: True if any RMOD or ASIRMOD ID exists in provided rmods dictionary, else False
        :rtype: boll
        """
        for rmod_obj, rmod_ids in rmods_dict.items():
            if rmod_ids:
                return True

        return False

    @log_input_and_output
    def _is_iot_cell(self):
        """
        Determines whether cell of given cell_type and cell_id is from NB-IoT cell technology.
        :return: info whether given cell is of NB-IoT technology
        :rtype: bool
        """
        iot_technologies = ["NB-IoT-FDD"]
        cell_technology = self._get_cell_technology()

        return cell_technology in iot_technologies

    @log_input_and_output
    def _get_cell_technology(self):
        if self._cell_type == "wcdma" or self._cell_type == "gsm":
            log_env_state("Cell technology is available only for NR and LTE cells")
            return None
        class_name = self._get_class_name_depending_on_rat()
        cells_runtime_distnames = self._get_runtime_cells_distnames()

        cells_technology = self._get_cells_technology_dict(
            class_name=class_name,
            cells_runtime_distnames=cells_runtime_distnames,
        )

        return cells_technology[str(self._cell_id)]

    @log_input_and_output
    def _get_cell_ids_for_all_rus(self):
        """
        Gets cell id for all RMODs and ASIRMODs with assignment to modules ids

        :return: list of cell ids for all rmods and asirmods e.g.:
         {'rmod': {'1': ['1']}, 'asirmod': {'1': ['211', '212'], '2': ['212']}}
        :rtype: dict
        """
        bts_info = self._api.get_bts_info(connection=self._connection_alias)
        rmod_objs = bts_info['radioModules']

        rmod_obj_cells = {}
        for rmod_obj, rmods_info in rmod_objs.items():
            rmod_id_cell_id = {}
            for rmod_info in rmods_info:
                rmod_id = rmod_info['id']['configuration'].split('/')[-1].split('-')[1]
                rmod_id_cell_id[rmod_id] = self._get_cell_ids_for_rmod(rmod_info)

            rmod_obj_cells[rmod_obj] = rmod_id_cell_id

        return rmod_obj_cells

    @log_input_and_output
    def _get_cell_ids_for_rmod(self, rmod_info):
        """
        Gets list of cell ids for provided RMOD/ASIRMOD.
        :param rmod_info: rmod object
        :type rmod_info: dict
        :return: list of cell ids for provided RMOD/ASIRMOD, e.g.: ["101", "103"]
        :rtype: list(str)
        """
        cell_class_name = self._get_class_name_depending_on_rat()
        cell_list = []
        for cell in rmod_info['carrierList']:
            try:
                cell_distname = cell['id']['configuration']
            except KeyError as e:
                if 'GNBTS' in cell['id']['internal']:  # GSM Cell case
                    continue
                raise e
            if cell_class_name in cell_distname:
                cell_id = cell_distname.split('/')[-2].split('-')[-1]
                if cell_id not in cell_list:
                    cell_list.append(cell_id)

        return cell_list

    @log_input_and_output
    def _get_name_of_id_param_depending_on_cell_type(self):
        param_dict = {"lte": "globalCellId", "nr": "globalCellId", "wcdma": "cellId", "gsm": None}
        return param_dict[self._cell_type]

    @log_input_and_output
    def _get_class_name_depending_on_rat(self):
        class_dict = {"lte": "LNCEL", "nr": "NRCEL", "wcdma": "WNCEL", "gsm": "GNCEL"}
        return class_dict[self._cell_type]

    @log_input_and_output
    def _get_runtime_cells_distnames(self):
        cells = self._api.get_cells_info(connection=self._connection_alias, cell_type=self._cell_type)
        return [cell["id"]["internal"] for cell in cells]

    @log_input_and_output
    def _get_cells_technology_dict(self, class_name, cells_runtime_distnames):
        cells_technology = {}

        for cell in cells_runtime_distnames:
            parameters = self._api.get_parameters_for(
                class_name=class_name, id_num=cell, connection=self._connection_alias
            )
            if cell in cells_technology:
                cells_technology[cell.split("-")[-1]].append(parameters["technology"])
            else:
                cells_technology[cell.split("-")[-1]] = parameters["technology"]
        return cells_technology

    @log_input_and_output
    def _get_statuses_of_all_rmods(self):
        """
        Gets statuses of all RMODs and ASIRMODs with assignment to modules ids
        :return: statuses for all rmods and asirmods e.g.:
                              {"rmod: {"1": {"operationalState": 'enabled', "administrativeState": "unlocked",
                                             "usageState": "Idle", "blockingState": "Unblocked"},
                                       "2": {"operationalState": 'enabled', "administrativeState": "unlocked",
                                             "usageState": "Idle", "blockingState": "Blocked"}},
                               "asirmod": {"1": {"operationalState": 'enabled', "administrativeState": "unlocked",
                                                 "usageState": "Idle", "blockingState": "Unblocked"},
                                           "2": {"operationalState": 'enabled', "administrativeState": "unlocked",
                                                 "usageState": "Idle", "blockingState": "Blocked"}}
                               }
        :rtype: dict
        """
        bts_rmods_info = self._api.get_bts_info(connection=self._connection_alias)["radioModules"]

        rmods_obj_statuses = {}
        for rmod_obj, rmods_info in bts_rmods_info.items():
            rmods_statuses = {}

            for rmod in rmods_info:
                rmod_id = rmod["id"]["configuration"].split('-')[-1]
                rmods_statuses[str(rmod_id)] = rmod["status"]

            rmods_obj_statuses[rmod_obj] = rmods_statuses

        return rmods_obj_statuses
